    # Find connected component with edges
    def bfs(start):
        visited = [False] * (n + 1)
        queue = [start]
        visited[start] = True
        visited_starts = {start}
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    visited_starts.add(v)
                    queue.append(v)
        return visited_starts

    # Check if all odd vertices are reachable from each other
    if odd_set:
        start = odd_vertices[0]
        visited = bfs(start)
        for v in odd_vertices[1:]:
