                return "-1"

    # If no edges and no odd vertices, empty path
    if m == 0 and not odd_vertices:
        return "0\n"

    # If no edges and we have odd vertices (imreachable), return -1
    if m == 0 and odd_vertices:
        return "-1"

    # Try to construct path
    path = []

