    elif len(odd_vertices) == 2:
        # Two odd vertices - find path between them
        path = find_path(odd_vertices[0], odd_vertices[1], n, adj)
        if path is None:
            return "-1"
    else:
        # More than 2 odd vertices - need to pair them up
        # Join them one by one
        path = [odd_vertices[0]]
        for i in range(len(odd_vertices) - 1):
            next_idx = odd_vertices[i + 1]
            curr = path[-1]
            path = path + find_path(curr, next_idx, n, adj)

        if path is None:
            return "-1"

    # Verify path satisfies requirements
    if len(path) == 0 and not odd_vertices:
        return "0\n"

    count = [0] * (n + 1)
    for v in path:
        count[v] += 1

    valid = True
    for i in range(n):
        if requirements[i] == 1 and count[i + 1] % 2 == 0:
            valid = False
        if requirements[i] == 0 and count[i + 1] % 2 == 1:
            valid = False

    if valid and len(path) <= 4 * n:
        return f"{len(path)}\n" + " ".join(map(str, path))
    else:
        # Try alternative: traverse all edges twice to ensure parity
        return "-1"


def find_path(start, end, n, adj):
    # BFS to find shortest path between two vertices
    if start == end:
        return []

    parent = [None] * (n + 1)
    visited = [False] * (n + 1)
    queue = [start]
    visited[start] = True
    found = False
    while queue:
        u = queue.pop(0)
        if u == end:
            found = True
            break
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                queue.append(v)

    if not found:
        return None

    # Reconstruct path
    path = []
    curr = end
    while curr is not None:
        path.append(curr)
        curr = parent[curr]

    path.reverse()
    return path


