    # Pattern: (x,y) -> (x+d,y-d) -> (x+d,y) -> (x,y+d) -> repeat

    # For each transformer, mark which (i,j, time) positions it occupies
    # time = i + j

    def get_transformer_pos(x, y, d, t, tau):
        if tau < t:
            return None
        dt = tau - t
        mod = dt % 4
        if mod == 0:
            return (x, y)
        elif mod == 1:
            return (x + d, y - d)
        elif mod == 2:
            return (x + d, y)
        else:  # mod == 3
