        u, v = map(int, line.split())
        adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    dist = []
    for i in range(1, n + 1):
        dist.append(bfs(i, n, adj))

    # Find 4 distinct cities with maximum total distance
    max_total = -1
    best_order = [1, 2, 3, 4]

    # Try all permutations of 4 cities
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j:
