def get_points(n: int, r: int) -> List[Tuple[int, int]]:
    # Generate all integer points within distance r from origin
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                points.append((x, y))
    return points

def dist_sq(p1: Tuple[int, int], p2: Tuple[int, int]) -> int:
    return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2

def compute_sum_sq(points: List[Tuple[int, int]], n: int) -> int:
    total = 0
    points = points[:n]
    for i in range(n):
        for j in range(i + 1, n):
            total += dist_sq(points[i], points[j])
    return total

def solve(n: int, r: int) -> Tuple[int, List[List[int]]]:
    points = get_points(n, r)

    best_score = -1
    best_config = None

    for combo in product(points, repeat=n):
        score = compute_sum_sq(combo, n)
        if score > best_score:
            best_score = score
            best_config = combo

    return best_score, best_config

