    a_cost: cost to remove an element
    b_cost: cost to change an element by at most 1
    arr: list of integers
    """

    # Total cost without any removal
    def total_cost_without_removal(arr, prime):
        """Calculate cost to make all elements divisible by prime without removal"""
        cost = 0
        for x in arr:
            if x % prime == 0:
                continue
            elif abs(x % prime - prime // 2) <= 1 and abs(x - (x // prime * prime)) <= b_cost:
                # Check if changing x by at most 1 makes it divisible
                lower = x - 1
                upper = x + 1
                if lower % prime == 0:
                    continue
                elif upper % prime == 0:
                    continue
                else:
                    cost += b_cost
            else:
                cost += b_cost
        return cost

    # Get small primes up to 100
    small_primes = []
    is_prime = [True] * 101
    for i in range(2, 101):
        if is_prime[i]:
            small_primes.append(i)
            for j in range(i*i, 101, i):
                is_prime[j] = False

