                    needs_change = True
                elif abs(x - prime - 1) <= 1 and (x + 1) % prime == 0:
                    needs_change = True
                elif (x - 1) % prime == 0 or (x + 1) % prime == 0:
                    needs_change = True

                if needs_change:
                    cost_change += b_cost
                else:
