            prefix_cost[i] = prefix_cost[i - 1] + (b_cost if x % prime != 0 else 0)

        for i in range(n - 1, -1, -1):
            x = arr[i]
            suffix_cost[i] = suffix_cost[i + 1] + (b_cost if x % prime != 0 else 0)

        # Note: This is a simplified version - actual optimal solution requires trying different primes
        min_cost = min(min(prefix_cost[k] + suffix_cost[n - k] + a_cost * k for k in range(n + 1)))

        return min_cost

    # For simplicity with the constraints, let's take a practical approach:
    # Try primes that divide the first few elements

    prime_candidates = []
