    # Calculate cost without any removal
    def calculate_all_cost(arr, prime):
        prefix = [0] * (len(arr) + 1)
        suffix = [0] * (len(arr) + 1)

        for i in range(len(arr)):
            cost = b_cost if arr[i] % prime != 0 else 0
