            suffix[i] = suffix[i + 1] + cost

        best = prefix[len(arr)]  # No removal

        for k in range(1, len(arr)):  # Remove subsegment of length k
            best = min(best, prefix[k] + suffix[k + len(arr) - 1])

        return best

    no_remove_cost = min(calculate_all_cost(arr, p) for p in prime_candidates)
