    memo = {}

    def can_force_win(a, b):
        """Returns True if current player can force opponent to lose (i.e., win the game)"""
        # If current position already has a^b >= n, the previous player lost
        # This shouldn't happen during normal play from valid positions
        if a ** b >= n:
            return False

        state = (a, b)
        if state in memo:
            return memo[state]

        # Current player wins if they can move to a state where opponent loses
        can_force = False

        # Option 1: Increase number of boxes (a)
        try:
            val = (a + 1) ** b
            if val < n and not can_force_win(a + 1, b):
                can_force = True
        except (OverflowError, MemoryError):
            pass

        # Option 2: Increase number of items (b)
        if not can_force:
            try:
                val = a ** (b + 1)
                if val < n and not can_force_win(a, b + 1):
                    can_force = True
            except (OverflowError, MemoryError):
                pass

        memo[state] = can_force
        return can_force

    # If Stas (first player) can force a win, Masha wins (Stas loses)
    # If Stas cannot force a win, Stas wins
    if can_force_win(a, b):
        return "Masha\n\n"
    else:
        return "Stas\n\n"


