import math

def solution(inp_str):
    lines = inp_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Compute LCM of all numbers
    lcm_val = a[0]
    for i in range(1, n):
        lcm_val = lcm(int(lcm_val), a[i])

    # Count divisors of lcm_val (excluding 1)
    count = 0
    d = 1
    while d * d <= lcm_val:
        if lcm_val % d == 0:
            if d * d == lcm_val:
                count += 1
            else:
                count += 2
        d += 1

    # Subtract 1 to exclude the divisor 1
    result = count - 1

    return str(result)

def lcm(a, b):
    return a // math.gcd(a, b) * b

