def solution(s):
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    a_set = set(a)
    reachable = set()

    # Compute all possible sums a1 + a2 mod M
    # This represents what residues can be obtained
    for x in a:
        for y in a:
            reachable.add((x + y) % m)

    unreachable = []
    for r in range(m):
        if r not in reachable:
            unreachable.append(r)

    if unreachable:
        unreachable.sort()
        result = f"{len(unreachable)}\n" + " ".join(map(str, unreachable))
    else:
        result = "0"

    return result

import sys

def solution(input_string):
    lines = input_string.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    S = sum(a)
    MOD = 998244353

    def inverse(x):
        return pow(x, MOD - 2, MOD)

    def harmonic(n):
        if n <= 0:
            return 0
        h = 0
        for i in range(1, n + 1):
            h = (h + inverse(i)) % MOD
        return h

    # If one player already has all biscuits, game ends immediately
    if S == 0:
        return "0"

    # If someone already has all biscuits
    if any(x == S for x in a):
        return "0"

    # Compute (n-1) * H_{n-1}
    H_nm_1 = harmonic(n - 1)
    coeff = (n - 1) * H_nm_1 % MOD

    # Compute sum of a_i * (S - a_i)
    sum_term = 0
    for ai in a:
        if ai > 0 and ai < S:
            sum_term = (sum_term + ai * (S - ai)) % MOD

    # Compute final answer: coeff * sum_term / S
    if S == 0:
        return "0"

    inv_S = inverse(S)
    ans = (coeff * sum_term) % MOD
    ans = (ans * inv_S) % MOD

    return str(ans)

def solution(input_str):
    sys.setrecursionlimit(100000)
    from functools import lru_cache
    import sys

    data = input_str.strip().split('\n')
    n = int(data[0])
    matrix = [[int(x) for x in line.split()] for line in data[1:]]

    MOD = 998244353

    D = [0] * (n + 1)
    D[0] = 1
    if n >= 1: D[1] = 0
    for i in range(2, n + 1):
        D[i] = (i - 1) * (D[i-1] + D[i-2]) % MOD

    @lru_cache(None)
    def dp(row, col, mask, pvals):
        if col == n:
            return 1
        if row == n:
            return 1

        res = 0
        pval = pvals[col] if col < len(pvals) else None

        for v in range(n):
            if mask & (1 << v):
                continue
            if pval is not None and v == pval:
                continue

            newmask = mask | (1 << v)
            newpvals = pvals + (v,) if v >= 0 else pvals

            if row == n - 1:
                res = (res + 1) % MOD
            else:
                sub = dp(row + 1, 0, 0, (v,))
                if sub == 0:
                    continue
                res = (res + sub) % MOD

        return res

    ans = 0
    for i in range(n):
        for j in range(n):
            target = matrix[i][j]
            used = 0
            prev = tuple(matrix[i-1][j:]) if i > 0 else tuple([None] * (n - j))

            for v in range(j):
                used |= (1 << (matrix[i][v] - 1))
            j = 0

            smaller = 0
            for v in range(target):
                if used & (1 << v):
                    continue
                if i > 0 and v + 1 == matrix[i-1][j]:
                    continue
                smaller += 1

            if smaller > 0:
                mass = (.used, j, prev)
                ways = dp(0, 0, 0, tuple())
                rem = D[n - 1 - i]
                ans = (ans + smaller * ways * rem) % MOD
                smalls = smaller
                smaller = min(smalles, n)

    return str(ans)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse coupons and extract (value, weight) pairs
    weights = []
    for line in lines[1:]:
        if line.strip():
            q, w = map(int, line.split())
            weights.append(w)

    # Sort weights in descending order
    weights.sort(reverse=True)

    # Find maximum k such that k*(k-1) <= n-1
    # and k <= m and k <= n
    k = 0
    for i in range(1, m + 1):
        if i * (i - 1) <= n - 1:
            if i <= n:
                k = i
        else:
            break

    # Take top k most expensive coupons
    result = sum(weights[:k])

    return str(result) + '\n'

def solution(data):
    lines = data.strip().split('\n')
    ts, tf, t = map(int, lines[0].split())
    n = int(lines[1])
    arrivals = list(map(int, lines[2].split()))

    # Generate candidate arrival times around visitor arrival times
    candidates = set()
    candidates.add(0)
    candidates.add(ts)
    for a in arrivals:
        candidates.add(a)
        if a >= 0:
            candidates.add(a - 1)
        if a >= t:
            candidates.add(a - t)
        if a < tf:
            candidates.add(a + 1)

    # Only consider candidates that are non-negative
    valid_candidates = sorted([c for c in candidates if c >= 0])

    best_arrival = 0
    min_wait = float('inf')

    for va in valid_candidates:
        # Build the service queue including Vasya
        extended = []
        for i, ar in enumerate(arrivals):
            if ar >= ts:
                extended.append((ar, False, i))  # (arrival_time, is_vasya, index)

        # Add Vasya as a candidate
        extended.append((va, True, -1))

        # Sort by arrival time (when equal times, existing visitors before Vasya)
        extended.sort()

        current = ts
        vasya_start = None

        for ar, is_vasya, orig_idx in extended:
            # Service can't start before arrival and before receptionist opens
            start = max(ar, current)

            # Service would complete after tf, so skip this service
            if start + t > tf:
                vasya_start = None
                break

            current = start + t

            if is_vasya:
                vasya_start = start

        # Calculate wait time if Vasya got served
        if vasya_start is not None:
            wait = vasya_start - va
            if wait < min_wait:
                min_wait = wait
                best_arrival = va

    return str(best_arrival) if min_wait != float('inf') else str(ts)


