    result = [0.0, 0.0, 0.0]
    for i in range(2, -1, -1):
        s = b[i]
        for j in range(i+1, 3):
            s -= A[i][j] * result[j]
        result[i] = s / A[i][i] if abs(A[i][i]) > 1e-10 else 0.0

    cx, cy, cz = result
    r = dist((cx, cy, cz), p4)
