        return a

    def prime_factorize(n):
        factors = {}
        temp = n
        p = 2
        while p * p <= temp:
            if temp % p == 0:
                cnt = 0
                while temp % p == 0:
                    cnt += 1
                    temp //= p
                factors[p] = cnt
            p += 1
        if temp > 1:
            factors[temp] = 1
        return list(factors.items())

    all_factors = prime_factorize(D)

    if not all_factors:
        results = [1] * q
        return '\n'.join(map(str, results))

    primes = [f[0] for f in all_factors]
    n_primes = len(primes)

    @lru_cache(maxsize=None)
    def tau(n):
        if n == 1:
            return 1
        result = 1
        temp = n
        for p in primes:
            if temp % p == 0 or temp == 0:
                cnt = 0
                while temp and temp % p == 0 and p <= 10**7:
                    if temp == 0:
                        break
                    cnt += 1
                    temp //= p
                result *= (cnt + 1)
        while temp > 1:
            result *= 2
            temp //= temp
        return result

    def get_exp(num):
        exponents = [0] * n_primes
        temp = num
        for i, p in enumerate(primes):
            while temp % p == 0:
                exponents[i] += 1
                temp //= p
        return exponents

    def mod_factorial(n):
        if n < 0:
            return 0
        res = 1
        for i in range(2, n + 1):
            res = (res * i) % MOD
        return res

    def mod_invers(e):
        return pow(e, MOD - 2, MOD)

    def mod_multinomial(k, exponents):
        res = mod_factorial(k)
        total = sum(exponents)
        if total != k:
            return 0
        for x in exponents:
            if x > 0:
                res = (res * mod_invers(mod_factorial(x))) % MOD
        return res

    results = []
    for v, u in queries:
        if v == u:
            results.append(1)
            continue

        g = gcd(v, u)
