    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Compute prefix sums S
    S = [0] * (n + 1)
    for i in range(n):
        S[i + 1] = S[i] + a[i]

    # Function to compute f(x) = max(C) - min(C)
    # where C[k] = S[k] - k*x
    def f(x):
        C = []
        for k in range(n + 1):
            C.append(S[k] - k * x)
        return max(C) - min(C)

    # Ternary search for optimal x
    low = -2000000
    high = 2000000

    for _ in range(100):
        m1 = low + (high - low) * 2 / 3
        m2 = high - (high - low) * 2 / 3
        if f(m1) < f(m2):
            high = m2
        else:
            low = m1

    return str(f(low))

