def solve_recursive(s, n, k, idx, balance, path):
    """
    idx: current position in string
    balance: current (wins - losses)
    path: current built string
    """
    if idx == n:
        return path if abs(balance) == k else None

    current_char = s[idx]
    options = []
    if current_char == '?':
        options = ['W', 'L', 'D']
    else:
        options = [current_char]

