        if char == 'W':
            new_balance = balance + 1
        elif char == 'L':
            new_balance = balance - 1
        else:
            new_balance = balance

        # Check constraints
        if idx + 1 < n:  # Not at final position
            if abs(new_balance) >= k:
                continue
        else:  # At final position
            if abs(new_balance) != k:
                continue

        new_path = path + char
        result = solve_recursive(s, n, k, idx + 1, new_balance, new_path)
