def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    idx = 1
    for _ in range(m):
        a, b, w = map(int, lines[idx].split())
        idx += 1
        adj[a].append((b, w))
        adj[b].append((a, w))

    idx = m + 1
    q_val = int(lines[idx])
    idx += 1

    d = [0] * (n + 1)
    g = [0] * (n + 1)
    visited = [False] * (n + 1)

    def dfs(u, p, dist):
        visited[u] = True
        d[u] = dist

        for v, w in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # Back-edge: u -> v forms a cycle
                cycle = abs(d[u] - d[v] + w)
                g[u] = gcd(g[u], cycle)
            else:
                dfs(v, u, dist + w)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1, 0)

    results = []
    for i in range(q_val):
        v, s, t = map(int, lines[idx + i * 3 : idx + (i + 1) * 3])

        if s == 0:
            results.append("YES")
        elif g[v] == 0:
            results.append("NO")
        else:
            if (t - s) % g[v] == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n'.join(results)

