                            prev = s2 if _ == 0 else (s2 + prev) if _ == 1 else (prev + s2)

                        if len(s) <= 10000:
                            sk = s

                    ac_count = count_AC(sk)
                    if ac_count == x:
                        answer = (s1, s2)
                        return True

        return False

    # Limited search for smaller k and n, m
    if k <= 5 and n <= 10 and m <= 10:
        if try_combinations():
            return f"{answer[0]}\n{answer[1]}\n"

    # For the actual problem, let's use a broader approach
    # Generate more strings and try memoized counting

    # The sequences grow: s_k = s_{k-2} + s_{k-1}
    # Let's trace patterns

    def get_sk_recursive(base1, base2, k):
        if k == 1:
            return base1
        elif k == 2:
            return base2
        elif k == 3:
            return base1 + base2
        elif k == 4:
            return base2 + base1 + base2
        elif k == 5:
            return (base1 + base2) + (base2 + base1 + base2)
        elif k <= 6:
            s5 = (base1 + base2) + (base2 + base1 + base2)
            s4 = base2 + base1 + base2
            return s4 + s5

    # More extensive search
    def gen_base_strings(length):
        results = []
        for i in range(length + 1):
            results.append('A' * i + 'C' * (length - i))
        return results

    base_n = gen_base_strings(n)
    base_m = gen_base_strings(m)

    for s1 in base_n:
        for s2 in base_m:
            k_str = get_sk_recursive(s1, s2, k)
            if k_str is not None and len(k_str) <= 10000:
                ac = count_AC(k_str)
                if ac == x:
                    return f"{s1}\n{s2}\n"

    return "Happy new year!\n"

