def solution(input_text):
    from collections import deque

    lines = input_text.strip().split('\n')
    if not lines:
        return ''

    first_line = lines[0].split()
    n = int(first_line[0])
    m = int(first_line[1])

    swapLR = 1 if len(first_line) > 3 else 0
    swapUD = 1 if len(first_line) > 4 else 0

    grid = [lines[i] for i in range(1, n + 1)]

    # Find finish
    finish = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'F':
                finish = (i, j)
                break
        if finish:
            break

    if not finish:
        return ''

    # BFS to find shortest path from (0,0) to finish
    # Directions: each move and its result based on swaps
    queue = deque([(0, 0)])
    visited = {(0, 0)}
    parent = {(0, 0): None}

    while queue:
        r, c = queue.popleft()

        if (r, c) == finish:
            break

        # Try moving in all 4 directions
        # Move is what would normally happen; after swap it's different
        directions = [
            (-1, 0, 'U'),  # normally press U to go up
            (1, 0, 'D'),   # normally press D to go down  
            (0, -1, 'L'),  # normally press L to go left
            (0, 1, 'R')    # normally press R to go right
        ]

        for dr, dc, normal_move in directions:
            nr, nc = r + dr, c + dc

            # Check bounds and whether cell is passable
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] != '*':
                if (nr, nc) not in visited:
                    visited.add((nr, nc))
                    parent[(nr, nc)] = (r, c, normal_move)
                    queue.append((nr, nc))

    # Reconstruct path - output moves in order from start to finish
    result = []
    curr = finish
    while curr != (0, 0):
        pr, pc, normal_move = parent[curr]
        result.append(normal_move)
        curr = (pr, pc)

    return '\n'.join(reversed(result))

def solution(input_str):
    parts = input_str.strip().split()
    if not parts:
        return "0"
    n = int(parts[0])

    if n == 0:
        return "0"

    MOD = 10**9 + 7

    # Aggregate dp[i][j][0] into a single value since we always take max
    # dp[i][j] = maximum matching where node (i,j) is not matched with child
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Fill from bottom (i=j=n) to top (i=j=0)
    for i in range(2 * n, -1, -1):
        for j in range(i + 1):
            if i == n and j == n:
                dp[i][j] = 0
                continue

            # Valid if we're in a valid state for bracket sequences
            if j > i:
                continue

            ans = 0

            # Try moving in valid directions
            if i < n:
                ans = max(ans, dp[i + 1][j] if i + 1 <= n and j <= i else 0)
            if j < i:
                ans = max(ans, dp[i][j + 1] if j + 1 <= i else 0)

            dp[i][j] = ans

    return str(dp[0][0] % MOD)

def solution(input_str):
    data = input_str.strip().split()
    if not data:
        return "-1\n"

    n = int(data[0])
    a = list(map(int, data[1:n+1]))

    valid_m = []

    for m in range(1, n + 1):
        if is_valid(m, a):
            valid_m.append(m)

    if not valid_m:
        return "-1\n"
    else:
        return " ".join(map(str, valid_m)) + "\n"

def is_valid(m, a):
    n = len(a)
    idx = 0

    for _ in range(m):
        if idx >= n:
            return False

        # Each partition must start with 1
        if a[idx] != 1:
            return False

        idx += 1

        # Try to match consecutive powers of 2
        expected = 2
        while idx < n:
            val = a[idx]
            if val == expected:
                idx += 1
                expected *= 2
            else:
                # This element is the remainder r for this partition
                idx += 1
                break

    return idx == n

